#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    auto startTime = chrono::steady_clock::now();
    auto elapsed = [&]() -> double {
        return chrono::duration<double>(chrono::steady_clock::now()-startTime).count();
    };

    int N;
    cin >> N;
    vector<double> x(N), y(N);
    for(int i=0;i<N;i++) cin >> x[i] >> y[i];

    vector<bool> is_prime(N+1, false);
    {
        vector<bool> sieve(N+1, true);
        if(N>=0) sieve[0]=false;
        if(N>=1) sieve[1]=false;
        for(int i=2;(long long)i*i<=N;i++)
            if(sieve[i])
                for(int j=i*i;j<=N;j+=i) sieve[j]=false;
        for(int i=0;i<=N;i++) is_prime[i]=sieve[i];
    }

    auto ddist = [&](int a, int b) -> double {
        double dx=x[a]-x[b], dy=y[a]-y[b];
        return sqrt(dx*dx+dy*dy);
    };

    // Precompute distance matrix for small N
    vector<vector<float>> D;
    bool useMat = (N <= 5000);
    if(useMat){
        D.assign(N, vector<float>(N, 0));
        for(int i=0;i<N;i++)
            for(int j=i+1;j<N;j++){
                float d = (float)ddist(i,j);
                D[i][j]=D[j][i]=d;
            }
    }

    auto dist = [&](int a, int b) -> double {
        if(useMat) return D[a][b];
        return ddist(a,b);
    };

    // penalty multiplier at step s (1-indexed), source city src
    auto mult = [&](int s, int src) -> double {
        return (s%10==0 && !is_prime[src]) ? 1.1 : 1.0;
    };

    // tour[0..N], tour[0]=tour[N]=0
    // step s: tour[s-1] -> tour[s]
    auto tourCost = [&](const vector<int>& t) -> double {
        double cost=0;
        for(int s=1;s<=N;s++){
            cost += dist(t[s-1],t[s]) * mult(s, t[s-1]);
        }
        return cost;
    };

    // Build nearest neighbor lists
    int K = min(N-1, 15);
    vector<vector<int>> nn(N, vector<int>(K));
    {
        vector<pair<float,int>> tmp;
        for(int i=0;i<N;i++){
            tmp.clear();
            for(int j=0;j<N;j++) if(j!=i) tmp.push_back({(float)dist(i,j),j});
            partial_sort(tmp.begin(), tmp.begin()+K, tmp.end());
            for(int k=0;k<K;k++) nn[i][k]=tmp[k].second;
        }
    }

    // Nearest neighbor heuristic
    vector<bool> visited(N, false);
    vector<int> tour;
    tour.reserve(N+1);
    tour.push_back(0);
    visited[0]=true;
    for(int step=1;step<N;step++){
        int last=tour.back();
        int best=-1; double bestD=1e18;
        for(int j=0;j<N;j++){
            if(!visited[j]){
                double d=dist(last,j);
                if(d<bestD){bestD=d;best=j;}
            }
        }
        tour.push_back(best);
        visited[best]=true;
    }
    tour.push_back(0);

    double bestCost = tourCost(tour);
    vector<int> bestTour = tour;

    // pos[city] = index in tour (1..N-1 for non-depot)
    vector<int> pos(N);
    auto buildPos = [&](){
        for(int i=0;i<=N;i++) pos[tour[i]]=i;
    };

    // Or-opt: relocate single city
    auto doRelocate = [&]() -> bool {
        bool improved=false;
        buildPos();
        for(int i=1;i<N && elapsed()<4.5;i++){
            int ci = tour[i];
            int prev = tour[i-1], next = tour[i+1];
            // cost of removing ci
            double remOld = dist(prev,ci)*mult(i,prev) + dist(ci,next)*mult(i+1,ci);
            // After removal, steps shift. Too complex to handle exactly with shifting.
            // Instead, just try swapping positions of two cities
            // Let's do simple swap of tour[i] and tour[j]
            for(int k=0;k<K;k++){
                int nbr = nn[ci][k];
                int j = pos[nbr];
                if(j==0||j==N) continue;
                if(abs(i-j)<=1) continue;
                // swap tour[i] and tour[j]
                swap(tour[i], tour[j]);
                // recompute affected edges
                double oldC=0, newC=0;
                // edges at i-1->i, i->i+1, j-1->j, j->j+1
                set<int> steps;
                steps.insert(i); steps.insert(i+1);
                steps.insert(j); steps.insert(j+1);
                swap(tour[i], tour[j]); // restore
                for(int s : steps){
                    if(s<1||s>N) continue;
                    oldC += dist(tour[s-1],tour[s])*mult(s,tour[s-1]);
                }
                swap(tour[i], tour[j]);
                for(int s : steps){
                    if(s<1||s>N) continue;
                    newC += dist(tour[s-1],tour[s])*mult(s,tour[s-1]);
                }
                if(newC < oldC - 1e-10){
                    pos[tour[i]]=i; pos[tour[j]]=j;
                    bestCost += newC - oldC;
                    improved=true;
                } else {
                    swap(tour[i], tour[j]);
                }
            }
        }
        return improved;
    };

    // 2-opt using NN lists
    auto do2opt = [&]() -> bool {
        bool improved=false;
        for(int i=1;i<N && elapsed()<4.5;i++){
            int ci = tour[i];
            for(int k=0;k<K;k++){
                int nbr = nn[ci][k];
                int j = pos[nbr];
                if(j<=i) continue;
                if(j>=N) continue;
                // reverse tour[i+1..j]? or tour[i..j]
                int len = j-i+1;
                if(len>500 && N>1000) continue;
                double oldSeg=0, newSeg=0;
                for(int s=i;s<=min(j+1,N);s++)
                    oldSeg += dist(tour[s-1],tour[s])*mult(s,tour[s-1]);
                reverse(tour.begin()+i, tour.begin()+j+1);
                for(int s=i;s<=min(j+1,N);s++)
                    newSeg += dist(tour[s-1],tour[s])*mult(s,tour[s-1]);
                if(newSeg < oldSeg - 1e-10){
                    bestCost += newSeg - oldSeg;
                    improved=true;
                    buildPos();
                } else {
                    reverse(tour.begin()+i, tour.begin()+j+1);
                }
            }
        }
        return improved;
    };

    buildPos();
    while(elapsed()<4.5){
        bool imp=false;
        imp |= do2opt();
        buildPos();
        imp |= doRelocate();
        buildPos();
        if(!imp) break;
    }

    if(tourCost(tour) < tourCost(bestTour)) bestTour=tour;

    cout << N+1 << "\n";
    for(int i=0;i<=N;i++) cout << bestTour[i] << "\n";
}
